def transform(grid):
    """Extend central rays from colored bars on opposite borders toward a marker."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max((v for row in g for v in row), key=lambda v: sum(x == v for r in g for x in r))
    from collections import Counter
    border = Counter(g[r][c] for r in range(h) for c in range(w)
                     if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and g[r][c] != bg)
    bar = border.most_common(1)[0][0]
    marks = [(r, c) for r in range(h) for c in range(w) if g[r][c] != bg and g[r][c] != bar]
    if not marks:
        return g
    ink = g[marks[0][0]][marks[0][1]]
    # Edge runs are bars; launch from their midpoint, continuing perpendicular to that edge.
    edges = []
    for c in range(w):
        if g[0][c] == bar: edges.append((0, c, 1, 0))
        if g[h-1][c] == bar: edges.append((h-1, c, -1, 0))
    for r in range(h):
        if g[r][0] == bar: edges.append((r, 0, 0, 1))
        if g[r][w-1] == bar: edges.append((r, w-1, 0, -1))
    # Group adjacent edge cells by side; select midpoint of each maximal run.
    for side in range(4):
        coords = []
        if side == 0: coords = [c for c in range(w) if g[0][c] == bar]
        elif side == 1: coords = [c for c in range(w) if g[h-1][c] == bar]
        elif side == 2: coords = [r for r in range(h) if g[r][0] == bar]
        else: coords = [r for r in range(h) if g[r][w-1] == bar]
        runs=[]
        for x in coords:
            if not runs or x > runs[-1][-1]+1: runs.append([x])
            else: runs[-1].append(x)
        for run in runs:
            x=run[(len(run)-1)//2]
            if side==0: r,c,dr,dc=0,x,1,0
            elif side==1: r,c,dr,dc=h-1,x,-1,0
            elif side==2: r,c,dr,dc=x,0,0,1
            else: r,c,dr,dc=x,w-1,0,-1
            r+=dr; c+=dc
            while 0<=r<h and 0<=c<w:
                if g[r][c] == ink:
                    g[r][c]=4
                    break
                if g[r][c] == bg: g[r][c]=ink
                r+=dr; c+=dc
    return g
